                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0], cc = pos[1];
                    for (int[] d : dirs) {
                        int nr = cr + d[0];
                        int nc = cc + d[1];
                        if (nr >= 0 && nr < rows && grid[nr] != null &&
                            nc >= 0 && nc < grid[nr].length &&
