    if (edges != null) {
        for (int[] e : edges) {
            if (e == null || e.length != 2) continue;
            int u = e[0], v = e[1];
            if (u < 0 || u >= n || v < 0 || v >= n) continue;
            adj[u].add(v);
            adj[v].add(u);
        }
    }
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -2); // -2 indicates unvisited
    int[] stack = new int[n];
    int top = 0;
    stack[top++] = 0;
    parent[0] = -1;
    int[] order = new int[n];
    int orderSize = 0;
    while (top > 0) {
        int node = stack[--top];
        order[orderSize++] = node;
        for (int nei : adj[node]) {
            if (parent[nei] == -2) {
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
    }
    boolean[] hasAppleSubtree = new boolean[n];
    int time = 0;
    for (int i = orderSize - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei : adj[node]) {
            if (parent[nei] == node) {
                if (hasAppleSubtree[nei]) {
                    time += 2;
                    has = true;
                }
            }
        }
        hasAppleSubtree[node] = has;
    }
    return time;
}

private boolean dfs(int node, List<Integer>[] adj, boolean[] visited, boolean[] hasApple, int[] time) {
    visited[node] = true;
    boolean has = hasApple[node];
    for (int nei : adj[node]) {
        if (!visited[nei]) {
            boolean childHas = dfs(nei, adj, visited, hasApple, time);
            if (childHas) {
                time[0] += 2;
                has = true;
            }
        }
    }
    return has;
}

