public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int num : nums) totalSum += num;
    // dp[k] holds all possible sums of subsets of size k
    @SuppressWarnings("unchecked")
    HashSet<Long>[] dp = new HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new HashSet<>();
    dp[0].add(0L);
    for (int num : nums) {
        // iterate k in reverse to avoid using updated values in the same iteration
        for (int k = Math.min(n / 2, n); k >= 1; k--) {
            for (Long prevSum : dp[k - 1]) {
                dp[k].add(prevSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        long target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    // Handle null or empty input
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    // If there's only one step, you can start at the top directly
    if (n == 1) {
        return 0;
    }
    // dp0 and dp1 represent the minimal cost to reach step i-2 and i-1 respectively
    int dpPrevPrev = 0; // cost to reach step 0
    int dpPrev = 0;     // cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int costFromPrev = dpPrev + cost[i - 1];
        int costFromPrevPrev = dpPrevPrev + cost[i - 2];
        int current = Math.min(costFromPrev, costFromPrevPrev);
        dpPrevPrev = dpPrev;
        dpPrev = current;
    }
    return dpPrev;
}

