public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }
    // If the string is too short to contain all possible k-length codes
    int totalCodes = 1 << k;
    if (s.length() < totalCodes) {
        return false;
    }
    // Use a boolean array to track seen codes
    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1; // mask to keep only k bits
    int current = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        // Shift left and add the new bit
        current = ((current << 1) & mask) | (s.charAt(i) - '0');
        // Once we have processed at least k characters, record the code
        if (i >= k - 1) {
            if (!seen[current]) {
                seen[current] = true;
                count++;
                // Early exit if all codes have been seen
                if (count == totalCodes) {
                    return true;
                }
            }
        }
    }
    return count == totalCodes;
}

