        minSum = Math.min(minSum, currentMin);
    }
    int absMax = Math.max(maxSum, -minSum);
    return absMax;
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int size = fibs.size();
        long next = (long)fibs.get(size - 1) + fibs.get(size - 2);
        if (next > k) {
            break;
        }
        fibs.add((int)next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        int f = fibs.get(i);
        if (remaining >= f) {
            remaining -= f;
            count++;
        }
        if (remaining == 0) {
            break;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    try {
        if (n <= 0 || k <= 0) return -1;
        java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
        for (int i = 1; (long)i * i <= n; i++) {
            if (n % i == 0) {
                factors.add(i);
                int other = n / i;
                if (other != i) {
                    factors.add(other);
                }
            }
        }
        java.util.Collections.sort(factors);
        if (k <= factors.size()) {
            return factors.get(k - 1);
        } else {
            return -1;
        }
    } catch (Exception e) {
        return -1;
    }
}

