    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - minSum; // how much we need to add to reach k

    // Increase characters from the end to keep the string lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each char can increase by at most 25 ('a'->'z')
        result[i] = (char) (result[i] + add);
        remaining -= add;
    }

    return new String(result);
}

