public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            if (((num >> i) & 1) == 1) {
                bitCount[i]++;
            }
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < 0 || low > high) {
        return result;
    }
    Deque<Long> queue = new ArrayDeque<>();
    // Start from each digit 0-9
    for (int i = 0; i <= 9; i++) {
        if (i <= high) {
            queue.add((long) i);
        }
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num >= low && num <= high) {
            result.add((int) num);
        }
        if (num > high) {
            continue;
        }
        long lastDigit = num % 10;
        // Generate next digits
        if (lastDigit > 0) {
            long nextNum = num * 10 + (lastDigit - 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
        if (lastDigit < 9) {
            long nextNum = num * 10 + (lastDigit + 1);
            if (nextNum <= high) {
                queue.add(nextNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long num = n;
    while (factor <= num) {
        long lower = num - (num / factor) * factor;
        long cur = (num / factor) % 10;
        long higher = num / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
        if (factor > Long.MAX_VALUE / 10) {
            break;
        }
        factor *= 10;
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // A number that is a power of two has exactly one bit set in its binary representation.
    // The expression (n & (n - 1)) clears the lowest set bit; if the result is zero,
    // then n had only one set bit.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0] != null ? mat[0].length : 0;
    if (n == 0) {
        return 0;
    }

    // DP arrays for four directions
    int[][] horiz = new int[m][n];
    int[][] vert  = new int[m][n];
    int[][] diag  = new int[m][n];
    int[][] anti  = new int[m][n];

    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        if (mat[i] == null) {
            continue; // treat null row as all zeros
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 1) {
                // Ensure we don't propagate values from non-1 cells
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                anti[i][j] = 0;
                continue;
            }
            horiz[i][j] = 1 + (j > 0 ? horiz[i][j - 1] : 0);
            vert[i][j] = 1 + (i > 0 ? vert[i - 1][j] : 0);
            diag[i][j] = 1 + (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0);
            anti[i][j] = 1 + (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0);

            int cellMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                   Math.max(diag[i][j], anti[i][j]));
            if (cellMax > maxLen) {
                maxLen = cellMax;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle negative numbers and Integer.MIN_VALUE safely using long
    long value = n;
    boolean negative = value < 0;
    if (negative) {
        value = -value; // safe because value is long
    }
    String digits = Long.toString(value);

    // Build the formatted string
    StringBuilder result = new StringBuilder();
    int len = digits.length();
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }

    // Append the first group (may be less than 3 digits)
    result.append(digits.substring(0, firstGroup));

    // Append remaining groups with dots
    for (int i = firstGroup; i < len; i += 3) {
        result.append('.');
        result.append(digits.substring(i, i + 3));
    }

    // Prepend minus sign if needed
    if (negative) {
        result.insert(0, '-');
    }

    return result.toString();
}

public static int squarePermutations(int[] A) {
    if (A == null) {
        return 0;
    }
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    int maxVal = 0;
    for (int v : A) {
        if (v > maxVal) {
            maxVal = v;
        }
    }
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long cur = dp[mask][last];
            if (cur == 0) {
                continue;
            }
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) {
                    continue;
                }
                if (isSquare[A[last] + A[next]]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }

    long total = 0;
    for (int last = 0; last < n; last++) {
        total += dp[fullMask][last];
    }
    return (int) total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] stack = new int[n + 1];
    int top = -1;
    long maxArea = 0;
    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && currentHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            long area = (long) height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return (int) maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.max(0, sum - (n - 1));
        int endRow = Math.min(m - 1, sum);
        if (sum % 2 == 0) {
            for (int i = endRow; i >= startRow; i--) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = startRow; i <= endRow; i++) {
                int j = sum - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    // Pairs of digits that are symmetric when rotated 180 degrees
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'8', '8'}, {'6', '9'}, {'9', '6'} };
    // Middle digits allowed for odd length numbers
    char[] middle = { '0', '1', '8' };

    // Initialize a StringBuilder with placeholder characters
    StringBuilder sb = new StringBuilder(n);
    for (int i = 0; i < n; i++) {
        sb.append(' ');
    }

    build(0, n - 1, sb, result, pairs, middle, n);
    return result;
}

private static void build(int left, int right, StringBuilder sb, List<String> result,
                          char[][] pairs, char[] middle, int n) {
    if (left > right) {
        result.add(sb.toString());
        return;
    }
    if (left == right) {
        for (char m : middle) {
            sb.setCharAt(left, m);
            result.add(sb.toString());
        }
        return;
    }
    for (char[] pair : pairs) {
        // Skip leading zero for numbers with length > 1
        if (left == 0 && n > 1 && pair[0] == '0') {
            continue;
        }
        sb.setCharAt(left, pair[0]);
        sb.setCharAt(right, pair[1]);
        build(left + 1, right - 1, sb, result, pairs, middle, n);
    }
}

public static boolean isBoomerang(int[][] points) {
    // Validate input
    if (points == null || points.length != 3) {
        return false;
    }
    for (int i = 0; i < 3; i++) {
        if (points[i] == null || points[i].length != 2) {
            return false;
        }
    }
    // Check that all points are distinct
    if ((points[0][0] == points[1][0] && points[0][1] == points[1][1]) ||
        (points[0][0] == points[2][0] && points[0][1] == points[2][1]) ||
        (points[1][0] == points[2][0] && points[1][1] == points[2][1])) {
        return false;
    }
    // Compute cross product to check collinearity
    int x1 = points[1][0] - points[0][0];
    int y1 = points[1][1] - points[0][1];
    int x2 = points[2][0] - points[0][0];
    int y2 = points[2][1] - points[0][1];
    int cross = x1 * y2 - y1 * x2;
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    long[] ugly = new long[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        long nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    long result = ugly[n - 1];
    if (result > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds int range");
    }
    return (int) result;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int maxLen = 1;
    int currentLen = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++;
        } else {
            if (currentLen > maxLen) {
                maxLen = currentLen;
            }
            currentLen = 1;
        }
    }
    if (currentLen > maxLen) {
        maxLen = currentLen;
    }
    return maxLen;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    long current = 1;
    for (int i = 0; i < n; i++) {
        result.add((int) current);
        if (current * 10 <= n) {
            current *= 10;
        } else if (current % 10 != 9 && current + 1 <= n) {
            current++;
        } else {
            while ((current / 10) % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    try {
        java.util.HashMap<Integer, Integer> freq = new java.util.HashMap<>();
        for (int num : nums) {
            freq.put(num, freq.getOrDefault(num, 0) + 1);
        }
        int sum = 0;
        for (java.util.Map.Entry<Integer, Integer> entry : freq.entrySet()) {
            if (entry.getValue() == 1) {
                sum += entry.getKey();
            }
        }
        return sum;
    } catch (Exception e) {
        return 0;
    }
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    // Split on space, preserving all empty tokens (including leading/trailing spaces)
    String[] parts = s.split(" ", -1);
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < parts.length; i++) {
        String word = parts[i];
        result.append(new StringBuilder(word).reverse());
        if (i < parts.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}
